    "options": [
     "Reduced gut motility",
     "Dilation of the bronchi",
     "Faster heart rate",
     "Dry mouth",
     "Constriction of the pupils"
    ],
    "answer": 4,
    "why": "Muscarinic receptors mediate parasympathetic effects: miosis, copious saliva, bronchoconstriction, slower heart, more gut motility.",
